// Playwright конфигурация для E2E тестирования FeatureFactory
import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  // Тесты находятся в tests/e2e/
  testDir: './tests/e2e',

  // Таймауты
  timeout: 30_000,
  expect: { timeout: 10_000 },

  // Параллельные тесты
  fullyParallel: true,
